import{_ as t,o as a,c as r,ah as s}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Report cards","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/bulletins.md","filePath":"src/en/guide/admin/bulletins.md"}'),o={name:"en/guide/admin/bulletins.md"};function n(i,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="report-cards" tabindex="-1">Report cards <a class="header-anchor" href="#report-cards" aria-label="Permalink to &quot;Report cards&quot;">​</a></h1><p>This page covers publishing report cards on the administration side — once teachers have entered their grades and appreciations for a given period (which is their own job, not yours), you&#39;re the one who triggers generating and releasing the report cards.</p><h2 id="publish-a-class-s-report-cards" tabindex="-1">Publish a class&#39;s report cards <a class="header-anchor" href="#publish-a-class-s-report-cards" aria-label="Permalink to &quot;Publish a class&#39;s report cards&quot;">​</a></h2><p>From <strong>School setup → Classes</strong>, click <strong>Bulletins</strong> on the row for the class you want.</p><p>To publish:</p><ol><li>Choose the <strong>Academic period</strong> you want from the dropdown at the top of the page.</li><li>Click <strong>Publish / republish bulletins</strong>.</li></ol><p>This generates (or regenerates) every student&#39;s report card in the class for that period, based on the grades and appreciations already entered.</p><p>On the <strong>first</strong> publication, each student&#39;s parents get an email and a notification: the report card is how they learn the period&#39;s results, not grade by grade. Republishing after a correction updates the already-published report card — students and parents always download the latest version — without notifying them a second time.</p><p>If no academic period is configured for this class&#39;s year, a message tells you so — go create one first in <a href="/era-guide/en/guide/admin/structure-etablissement.html">School structure</a>.</p><h2 id="track-and-download-report-cards" tabindex="-1">Track and download report cards <a class="header-anchor" href="#track-and-download-report-cards" aria-label="Permalink to &quot;Track and download report cards&quot;">​</a></h2><p>The table below the period selector lists each student in the class with:</p><ul><li><strong>Status</strong> — &quot;Not published&quot;, or the date the report card was published.</li><li>A download button (icon), available as soon as a report card has been generated for that student.</li></ul><h2 id="grade-summaries" tabindex="-1">Grade summaries <a class="header-anchor" href="#grade-summaries" aria-label="Permalink to &quot;Grade summaries {#grade-summaries}&quot;">​</a></h2><p><strong>Teaching → Grade summaries</strong> lists the year&#39;s classes and, for each one, two ways in. The <strong>Grade summary</strong> button on a class&#39;s report cards page leads to the same place.</p><ul><li><strong>Grade summary</strong> — every student against every subject, for the chosen period. Each cell gives the student&#39;s average in the subject, with the detail by evaluation type underneath (D = homework, C = composition…). A dot marks an option the student doesn&#39;t take; a dropped specialty is flagged. The last columns give the overall average, then the student&#39;s rank in the class; the last three rows, the class average, the lowest and the highest.</li><li><strong>A subject</strong> — the subject&#39;s mark sheet: every evaluation of the period, each student&#39;s grade as entered (on the evaluation&#39;s own scale, with bonus or malus, absent or excused), then their subject average and their rank in the subject. Only the students who take the subject appear; out-of-average types are flagged.</li></ul><p>Averages are <strong>exactly the report cards&#39;</strong>: a summary can never show a different average from the same student&#39;s report card. Two students with the same average (to the hundredth, as shown) share a rank, &quot;2nd (tied)&quot;, and the next rank is skipped (1st, 2nd, 2nd, 4th).</p><p>Each screen downloads:</p><ul><li>as a <strong>PDF</strong>, to print or bring to the class council;</li><li>as an <strong>Excel</strong> file (.xlsx), to work on in a spreadsheet. A class&#39;s file has two sheets: the summary, and the <strong>council appreciations</strong> to fill in.</li></ul><p>In the class summary, the icons next to a student&#39;s name download:</p><ul><li>their <strong>grade report</strong> as a PDF: each of their evaluations, subject by subject, with their averages and their rank in the class;</li><li>their <strong>Excel file</strong>, across all subjects, to fill in and import (see below).</li></ul><h3 id="import-from-excel" tabindex="-1">Import grades and appreciations from Excel <a class="header-anchor" href="#import-from-excel" aria-label="Permalink to &quot;Import grades and appreciations from Excel {#import-from-excel}&quot;">​</a></h3><p>The downloaded Excel file is also the template: fill it in, then send it back with the <strong>Import</strong> button of the same screen.</p><ul><li><strong>A subject&#39;s grades and appreciations</strong> — from the subject&#39;s mark sheet. In each evaluation column, type the grade on the evaluation&#39;s scale (12 or 12.5), &quot;Absent&quot; (or &quot;abs&quot;) or &quot;Excused&quot; (&quot;Dispensé&quot; in French); in the <strong>Appreciation</strong> column, the report card appreciation (one column per rubric if the school has <a href="#appreciation-rubrics">appreciation rubrics</a>). Evaluations must first be created in ERA: the import fills in their grades, it doesn&#39;t create any. A bonus or malus already given is kept. Admins, the subject&#39;s teacher and the class&#39;s homeroom teacher only.</li><li><strong>A student&#39;s grades and appreciations, all subjects</strong> — from the class summary: the Excel icon next to the student&#39;s name downloads their file, the import icon sends it back. The file has two sheets: &quot;Grades&quot;, one row per evaluation of the period in every subject (type the grade in the <strong>Grade</strong> column), and &quot;Appreciations&quot;, one row per subject (one column per rubric, if any). Only the Excel file is accepted, not a CSV. Admins and the class&#39;s homeroom teacher only.</li><li><strong>Council appreciations</strong> — from the class summary, &quot;Council appreciations&quot; sheet: general appreciation, conduct, and an &quot;x&quot; for each distinction or warning (congratulations, compliments, encouragements, work warning, conduct warning). Admins and the homeroom teacher only.</li></ul><p>The import&#39;s rules:</p><ul><li><strong>an empty cell changes nothing</strong> already in ERA: you can import the same file again after completing it. For distinctions, on a filled-in row, an empty cell means &quot;no&quot;;</li><li><strong>all or nothing</strong>: the whole file is checked before anything is saved. If it has an error (a grade off the scale, an unknown word, an unknown student), nothing is saved and each row to fix is listed;</li><li>don&#39;t change the first column (<strong>Student no.</strong>, or <strong>Reference</strong> in a student&#39;s file): it links each row to its student, evaluation or subject. The file of another class, subject, period or student is refused, as is any import into a closed period;</li><li>a CSV saved from Excel is accepted too, as long as its column headers are the downloaded file&#39;s.</li></ul><h2 id="appreciation-rubrics" tabindex="-1">Appreciation rubrics <a class="header-anchor" href="#appreciation-rubrics" aria-label="Permalink to &quot;Appreciation rubrics {#appreciation-rubrics}&quot;">​</a></h2><p>By default, a subject&#39;s appreciation is a free comment. You can split it into <strong>appreciation rubrics</strong>: for instance &quot;Attitude&quot;, &quot;Progression&quot; and &quot;Advice&quot;. Not to be confused with subject sections (&quot;Core curriculum&quot;, &quot;Sciences&quot;…), which group subjects on the report card.</p><ol><li>Open <strong>App settings</strong>, <strong>Bulletins</strong> section.</li><li>Under <strong>Subject appreciation rubrics</strong>, click <strong>Add a rubric</strong> and name it (60 characters at most). Six rubrics at most.</li><li>Order them with the arrows, as the report card will show them, then click <strong>Save changes</strong>.</li></ol><p>Then:</p><ul><li>teachers fill in each rubric for each student, on the appreciations page as in the subject&#39;s Excel file, which has one column per rubric;</li><li>the report card shows the filled-in rubrics one after the other in the appreciation cell: &quot;Attitude: … · Progression: …&quot;.</li></ul><p><strong>Renaming</strong> a rubric keeps the texts already entered. <strong>Removing</strong> a rubric hides it everywhere, but its texts stay saved. Without any rubric, the appreciation is a free comment again. A free comment entered before the rubrics were added stays on the report card as long as no rubric is filled in for that student.</p><h2 id="report-card-template" tabindex="-1">Report card template <a class="header-anchor" href="#report-card-template" aria-label="Permalink to &quot;Report card template&quot;">​</a></h2><p>The visual template used (Classic, Compact, or Traditional French-style) is chosen per class, in the class&#39;s form — see <a href="/era-guide/en/guide/admin/structure-etablissement.html#classes">School structure</a>. If no template is chosen for a class, the school&#39;s default template applies.</p><p>Whatever the template, the report card&#39;s subjects follow the <a href="/era-guide/en/guide/admin/structure-etablissement.html#subjects-by-department">subjects by department</a> setup:</p><ul><li>they are grouped under their <strong>heading</strong> (&quot;Tronc commun&quot;, &quot;Sciences&quot;…), in the <strong>order</strong> given; subjects without a heading come without a title;</li><li><strong>specialties</strong> form a separate block, &quot;Enseignements de spécialité&quot;: first those the student keeps, then those they dropped, marked &quot;(abandonnée)&quot;.</li></ul><p>The <strong>Traditional</strong> template adds one column per evaluation type that counts in the average (the student&#39;s homework average, composition average…) and a &quot;Moy. × coef.&quot; column. Types <a href="/era-guide/en/guide/admin/structure-etablissement.html#evaluation-types">not counted</a> don&#39;t appear there.</p><p>A published report card is a fixed document: a setup change only shows once the class&#39;s report cards are published again.</p>',37)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
